scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_92'] || []

control 'CKV_AWS_92' do
  title 'Ensure the ELB has access logging enabled'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_elb resources that actually exist, read through the stock
    inspec-aws aws_elb resource.
  DESC

  desc 'rationale', <<~RATIONALE
    Without access logs the load balancer is the one hop in the request path
    that keeps no record. Client address, path and response code for traffic
    that never reached a backend exist nowhere else, which is exactly the
    traffic an investigation needs.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: an access_logs block is present and not disabled
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_elb:

      resource "aws_elb" "app" {
        name            = "app-elb"
        subnets         = var.subnet_ids
        security_groups = [aws_security_group.elb.id]

        listener {
          instance_port      = 8080
          instance_protocol  = "https"
          lb_port            = 443
          lb_protocol        = "https"
          ssl_certificate_id = aws_acm_certificate.app.arn
        }

        access_logs {
          enabled       = true
          bucket        = aws_s3_bucket.elb_logs.id
          bucket_prefix = "app-elb"
          interval      = 60
        }
      }

    Out of band — aws_elb:

      aws elb modify-load-balancer-attributes --load-balancer-name app-elb --load-balancer-attributes '{"AccessLog":{"Enabled":true,"S3BucketName":"my-elb-logs","EmitInterval":60,"S3BucketPrefix":"app-elb"}}'

    Note (aws_elb): The log bucket needs a policy allowing the regional ELB
    account principal to PutObject, or the attribute update is rejected
    outright.
  FIX

  tag checkov_id:            'CKV_AWS_92'
  tag checkov_category:      'LOGGING'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'custom'
  tag tf_resources:          %w[aws_elb]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/elb'
  tag nist:                  ['AU-2', 'AU-12']
  tag nist_r4:               ['AU-2', 'AU-12']
  tag cci:                   ['CCI-000169', 'CCI-000172']
  tag ksi:                   ['KSI-MLA-LOG']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  # Enumerated at control scope, then each asset asserted on its own. The
  # resource is an ARGUMENT to `describe`, which evaluates on the control --
  # calling it inside the block would defer it into the example.
  #
  # Every call carries aws_region: a stock resource otherwise reads only the
  # region the connection was built with, and every other region's resources
  # report as absent, which renders Not Applicable rather than unexamined.
  found = checkov_scan_regions(scan_regions).flat_map do |region|
    aws_elbs(aws_region: region).load_balancer_names.to_a.map { |id| [id, region] }
  end

  # A plural resource whose table is built from the API response returns nil for
  # a column that does not exist, rather than raising. Passing that on gives
  # "`[:x]` must be provided" and kills the control. Blank ids are separated out
  # and asserted on below, so a wrong `ids` column is a visible failure rather
  # than a crash or a silent Not Applicable.
  unusable = found.count { |id, _r| "#{id}".strip.empty? }
  found = found.reject { |id, _r| "#{id}".strip.empty? }
  in_scope = found.reject { |id, _r| checkov_exempt?(id: id, type: 'aws_elb', rules: exempt) }

  if unusable.positive?
    describe "aws_elb enumeration" do
      it 'produced usable identifiers' do
        expect(unusable).to eq(0),
          "#{unusable} row(s) had a blank id — the `ids` column in resource_map.yml "          'likely names a field this resource does not expose'
      end
    end
  end

  applicable = !in_scope.empty?
  impact 0.5
  impact 0.0 unless applicable
  only_if('no aws_elb in scope') { applicable }

  in_scope.each do |id, region|
    describe aws_elb(load_balancer_name: id, aws_region: region) do
      its('access_log_enabled?') { should eq true }
    end
  end
end
